Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  Blob *blob;
  size_t width, height;
  ssize_t y;

  if ((image = AcquireImage(image_info, exception)) == (Image *) NULL)
    return (Image *) NULL;
  blob = OpenBlob(image_info, ReadMode, exception);
  if (blob == (Blob *) NULL) {
    ThrowBlobException(DelegateError, "UnableToOpenBlob", image->filename);
    return (Image *) NULL;
  }

  if (ReadBlobMSBLong(blob, &width) != sizeof(size_t) ||
      ReadBlobMSBLong(blob, &height) != sizeof(size_t)) {
    ThrowBlobException(CorruptImageError, "UnableToReadSize", image->filename);
    return (Image *) NULL;
  }

  image->columns = width;
  image->rows = height;

  if (image_info->ping) {
    CloseBlob(blob);
    return image;
  }

  if (SetImageExtent(image, image->columns, image->rows) != MagickBooleanValueTrue) {
    CloseBlob(blob);
    return (Image *) NULL;
  }

  for (y = 0; y < (ssize_t) image->rows; y++) {
    register PixelPacket *q;
    ssize_t x;

    q = SetImagePixels(image, 0, y, image->columns, 1);
    if (q == (PixelPacket *) NULL) {
      CloseBlob(blob);
      return (Image *) NULL;
    }

    for (x = 0; x < (ssize_t) image->columns; x++) {
      unsigned char bit;
      if (ReadBlobByte(blob, &bit) != 1) {
        ThrowBlobException(CorruptImageError, "PrematureEndOfFile", image->filename);
        return (Image *) NULL;
      }

      q->red = ScaleCharToQuantum(bit ? 255 : 0);
      q->green = q->red;
      q->blue = q->red;
      q->opacity = OpaqueOpacity;
      q++;
    }

    if (!SyncImagePixels(image)) {
      CloseBlob(blob);
      return (Image *) NULL;
    }
  }

  CloseBlob(blob);
  return image;
}

Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image;
  unsigned int status = MagickFalse;

  if ((image_info == (ImageInfo *) NULL) || (exception == (ExceptionInfo *) NULL)) {
    return (Image *) NULL;
  }

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL) {
    return (Image *) NULL;
  }

  // Open file and read dimensions
  if (image->blob == (void *) NULL) {
    CatchException(exception);
    return (Image *) NULL;
  }

  // Initialize colormap and check for ping request
  if (image->ping) {
    CloseBlob(image);
    return GetFirstImageInList(image);
  }

  // Set image extent and read pixel data
  status = ReadImagePixels(image, exception);
  if (!status) {
    DestroyImage(&image);
    return (Image *) NULL;
  }

  // Final checks
  if (EOFCheck(image, exception)) {
    DestroyImage(&image);
    return (Image *) NULL;
  }

  return image;
}

Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image;

  assert(image_info != (const ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL)
    return (Image *) NULL;

  if (image->storage_class == PseudoClass) {
    if (AllocateImageColormap(image, 2, exception) != MagickTrue) {
      DestroyImage(image);
      return (Image *) NULL;
    }
    image->colormap[0].red = 0;
    image->colormap[0].green = 0;
    image->colormap[0].blue = 0;
    image->colormap[1].red = 65535;
    image->colormap[1].green = 65535;
    image->colormap[1].blue = 65535;
  }

  if (image->ping != MagickFalse) {
    (void) CloseBlob(image);
    return image;
  }

  if (ReadBlob(image, sizeof(unsigned int), &image->columns) != sizeof(unsigned int) ||
      ReadBlob(image, sizeof(unsigned int), &image->rows) != sizeof(unsigned int)) {
    ThrowReaderException(CorruptImageError, UnexpectedEndOfFile, image);
  }

  if (AcquireImagePixels(image, 0, 0, image->columns, image->rows, exception) == (PixelPacket *) NULL) {
    ThrowReaderException(ResourceLimitError, MemoryAllocationFailed, image);
  }

  {
    unsigned int row;
    for (row = 0; row < image->rows; row++) {
      unsigned char *bits = (unsigned char *) AcquireMemory(image->columns / 8 + 1);
      if (ReadBlob(image, image->columns / 8 + 1, bits) != (size_t)(image->columns / 8 + 1)) {
        RelinquishMemory(bits);
        ThrowReaderException(CorruptImageError, UnexpectedEndOfFile, image);
      }
      {
        register PixelPacket *q;
        register unsigned int bit;
        register unsigned int column;
        q = SetImagePixels(image, 0, row, image->columns, 1, exception);
        if (q == (PixelPacket *) NULL)
          break;
        for (column = 0; column < image->columns; column++) {
          bit = (column % 8);
          q->index = ((bits[column / 8] >> bit) & 0x01);
          q++;
        }
        if (SyncImagePixels(image, exception) == MagickFalse) {
          RelinquishMemory(bits);
          ThrowReaderException(ResourceLimitError, MemoryAllocationFailed, image);
        }
        RelinquishMemory(bits);
      }
    }
  }

  if (EOFBlob(image)) {
    (void) CloseBlob(image);
    return image;
  }

  ThrowReaderException(CorruptImageError, UnexpectedEndOfFile, image);
}

Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  ssize_t y;
  Quantum *q;

  assert(image_info != (ImageInfo *)NULL);
  assert(image_info->signature == MagickSignature);

  image = AcquireImage(image_info, exception);
  if (image == (Image *)NULL)
    return (Image *)NULL;

  /* Open image file and read dimensions */
  if (image->blob == (void *)NULL)
  {
    ThrowFileException(exception, FileOpenError, UnableToOpenImage,
      image_info->filename);
    return (Image *)NULL;
  }

  /* Initialize image colormap */
  if (image->colors > 1)
  {
    if (AllocateImageColormap(image, exception) == MagickFalse)
      return (Image *)NULL;
  }

  /* If ping, skip reading pixel data */
  if (image->ping != MagickFalse)
  {
    CloseBlob(image);
    return GetFirstImageInList(image);
  }

  /* Set image extent */
  image->columns = 640;
  image->rows = 480;

  /* Read pixel data row by row */
  for (y = 0; y < (ssize_t)image->rows; y++)
  {
    q = QueueAuthenticPixels(image, 0, (ssize_t) y, image->columns, 1, exception);
    if (q == (Quantum *) NULL)
      break;
    if (ReadBlob(image, image->columns, q) != image->columns)
    {
      if (y == 0)
        InheritException(exception, &image->exception);
      break;
    }
    if (SyncAuthenticPixels(image, exception) == MagickFalse)
      break;
  }

  if (y < (ssize_t) image->rows)
  {
    InheritException(exception, &image->exception);
    return (Image *) NULL;
  }

  return image;
}
